import java.util.*;import org.apache.ibatis.session.*;import org.mybatis.spring.SqlSessionFactoryBean;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.core.io.FileSystemResource;import com.project.system.domain.SysUser;import com.project.system.mapper.SysUserMapper;
public class UserIdentityFilterCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);}
 public static void main(String[]args)throws Exception{SqlSessionFactoryBean factory=new SqlSessionFactoryBean();factory.setDataSource(new DriverManagerDataSource("jdbc:mysql://127.0.0.1:13306/school_one_card2?useSSL=false&serverTimezone=Asia/Shanghai","root",""));factory.setTypeAliasesPackage("com.project.system.domain");factory.setMapperLocations(new org.springframework.core.io.Resource[]{new FileSystemResource("school_one_card2/src/main/resources/mapper/system/SysUserMapper.xml")});try(SqlSession s=factory.getObject().openSession()){SysUserMapper mapper=s.getMapper(SysUserMapper.class);SysUser q=new SysUser();List<SysUser> all=mapper.selectUserList(q);q.setIdentity("教师/职工");List<SysUser> staff=mapper.selectUserList(q);check(!staff.isEmpty()&&staff.size()<all.size()&&staff.stream().allMatch(u->"教师/职工".equals(u.getIdentity())),"staff identity filters actual mapper results");q.setLoginName(staff.get(0).getLoginName());check(mapper.selectUserList(q).size()==1,"identity combines with student number");q.setLoginName(null);q.setIdentity("本科生");check(mapper.selectUserList(q).stream().allMatch(u->"本科生".equals(u.getIdentity())),"undergraduate identity excludes staff");q.setIdentity("不存在的身份");check(mapper.selectUserList(q).isEmpty(),"unknown identity returns no users");q.setIdentity("");check(mapper.selectUserList(q).size()==all.size(),"all identity restores unfiltered users");System.out.println("all="+all.size()+" staff="+staff.size());}}
}
